using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search functionality to the research agent.
/// Uses a configurable search endpoint (defaults to a mock for demonstration).
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;
    private readonly string? _searchEndpoint;

    public WebSearchTool(HttpClient httpClient, string? searchEndpoint = null)
    {
        _httpClient = httpClient;
        _searchEndpoint = searchEndpoint;
    }

    [Description("Searches the web for information on a given query. Returns a list of relevant results with titles, snippets, and URLs.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5,
        CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(query))
        {
            return "Error: Search query cannot be empty.";
        }

        maxResults = Math.Clamp(maxResults, 1, 10);

        if (!string.IsNullOrEmpty(_searchEndpoint))
        {
            return await ExecuteLiveSearchAsync(query, maxResults, cancellationToken);
        }

        // Simulated search results for demonstration
        return GenerateSimulatedResults(query, maxResults);
    }

    private async Task<string> ExecuteLiveSearchAsync(string query, int maxResults, CancellationToken cancellationToken)
    {
        try
        {
            var requestUrl = $"{_searchEndpoint}?q={Uri.EscapeDataString(query)}&count={maxResults}";
            var response = await _httpClient.GetAsync(requestUrl, cancellationToken);
            response.EnsureSuccessStatusCode();

            var content = await response.Content.ReadAsStringAsync(cancellationToken);
            return content;
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed: {ex.Message}. Please try a different query or try again later.";
        }
    }

    private static string GenerateSimulatedResults(string query, int maxResults)
    {
        var results = new List<object>();
        for (int i = 1; i <= maxResults; i++)
        {
            results.Add(new
            {
                title = $"Result {i}: Information about {query}",
                snippet = $"This is a simulated search result #{i} containing relevant information about '{query}'. " +
                          $"In a production environment, this would contain real web search data.",
                url = $"https://example.com/search/{Uri.EscapeDataString(query)}/result{i}"
            });
        }

        return JsonSerializer.Serialize(new { query, results }, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using System.Text;
using System.Text.Json;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking functionality for the research agent to organize findings.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<Note> _notes = [];

    [Description("Saves a research note with a title and content. Use this to record important findings from web searches.")]
    public string SaveNote(
        [Description("A short title summarizing the note")] string title,
        [Description("The content of the note with key findings")] string content,
        [Description("Optional source URL where the information was found")] string? sourceUrl = null)
    {
        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(content))
        {
            return "Error: Both title and content are required.";
        }

        var note = new Note(title.Trim(), content.Trim(), sourceUrl?.Trim(), DateTime.UtcNow);
        _notes.Add(note);

        return $"Note saved successfully: \"{title}\" (Note #{_notes.Count})";
    }

    [Description("Retrieves all saved research notes. Use this to review findings before creating a summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===");
        sb.AppendLine();

        for (int i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"--- Note #{i + 1}: {note.Title} ---");
            sb.AppendLine(note.Content);
            if (!string.IsNullOrEmpty(note.SourceUrl))
            {
                sb.AppendLine($"Source: {note.SourceUrl}");
            }

            sb.AppendLine();
        }

        return sb.ToString();
    }

    [Description("Searches through saved notes for a specific keyword or phrase.")]
    public string SearchNotes(
        [Description("The keyword or phrase to search for in saved notes")] string keyword)
    {
        if (string.IsNullOrWhiteSpace(keyword))
        {
            return "Error: Search keyword cannot be empty.";
        }

        var matches = _notes
            .Select((note, index) => (note, index))
            .Where(x => x.note.Title.Contains(keyword, StringComparison.OrdinalIgnoreCase) ||
                        x.note.Content.Contains(keyword, StringComparison.OrdinalIgnoreCase))
            .ToList();

        if (matches.Count == 0)
        {
            return $"No notes found matching '{keyword}'.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"Found {matches.Count} note(s) matching '{keyword}':");
        sb.AppendLine();

        foreach (var (note, index) in matches)
        {
            sb.AppendLine($"--- Note #{index + 1}: {note.Title} ---");
            sb.AppendLine(note.Content);
            sb.AppendLine();
        }

        return sb.ToString();
    }

    private sealed record Note(string Title, string Content, string? SourceUrl, DateTime CreatedAt);
}

