using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

builder.Configuration.AddEnvironmentVariables("RESEARCH_AGENT_");

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? throw new InvalidOperationException(
        "AI:ApiKey is not configured. Set the RESEARCH_AGENT_AI__ApiKey environment variable or configure via user-secrets.");
var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(sp =>
    new Microsoft.Extensions.AI.OpenAIChatClient(
        new OpenAI.Chat.ChatClient(model: modelId, apiKey: apiKey)));

builder.Logging.SetMinimumLevel(LogLevel.Warning);

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var loggerFactory = host.Services.GetRequiredService<ILoggerFactory>();

// Create tool instances
var searchEndpoint = builder.Configuration["Search:Endpoint"];
var webSearch = new WebSearchTool(new HttpClient(), searchEndpoint);
var noteTaking = new NoteTakingTool();

// Register tools with the agent
var tools = new List<AITool>
{
    AIFunctionFactory.Create(webSearch.SearchWebAsync),
    AIFunctionFactory.Create(noteTaking.SaveNote),
    AIFunctionFactory.Create(noteTaking.GetAllNotes),
    AIFunctionFactory.Create(noteTaking.SearchNotes),
};

const string agentInstructions = """
    You are a research agent. Your job is to research a topic thoroughly by:
    1. Searching the web for relevant information using multiple queries
    2. Taking notes on key findings from each search
    3. Reviewing your notes to identify patterns and important details
    4. Providing a comprehensive summary of your research

    Research strategy:
    - Start with a broad search, then narrow down to specific aspects
    - Save important findings as notes with clear titles
    - Search for at least 2-3 different angles on the topic
    - After gathering enough information, review all notes and synthesize a summary

    Always end by providing a well-structured summary of your findings.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: agentInstructions,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes",
    tools: tools,
    loggerFactory: loggerFactory);

// Get the research topic
string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine()?.Trim() ?? "artificial intelligence";
}

Console.WriteLine();
Console.WriteLine($"🔍 Researching: {topic}");
Console.WriteLine(new string('─', 50));

var session = await agent.CreateSessionAsync(cancellationToken: CancellationToken.None);
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var prompt = $"Please research the following topic and provide a comprehensive summary: {topic}";

await foreach (var update in agent.RunStreamingAsync(prompt, session, runOptions))
{
    if (update.Text is { Length: > 0 } text)
    {
        Console.Write(text);
    }
}

Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine("✅ Research complete.");

